## Code Example
```javascript
function maxIntervalValue(A, B, k) {
  const n = A.length;
  const PA = [0], PB = [0];
  for (let i = 1; i <= n; i++) {
    PA[i] = PA[i-1] + A[i-1];
    PB[i] = PB[i-1] + B[i-1];
  }
  const dp = Array(n+1).fill(null).map(() => Array(k+1).fill(-Infinity));
  const prev = Array(n+1).fill(null).map(() => Array(k+1).fill(null));
  dp[0][0] = 0;
  for (let r = 1; r <= n; r++) {
    for (let t = 1; t <= k; t++) {
      for (let l = 1; l <= r; l++) {
        const val = (PA[r] - PA[l-1]) * (PB[r] - PB[l-1]);
        const candidate = dp[l-1][t-1] + val;
        if (candidate > dp[r][t]) {
          dp[r][t] = candidate;
          prev[r][t] = { l, r: l-1 };
        }
      }
    }
  }
  return dp[n][k];
}
```

